   127  static uint16_t
   128  _cdf_tole2(uint16_t sv)
   129  {
   130          uint16_t rv;
   131          uint8_t *s = RCAST(uint8_t *, RCAST(void *, &sv));
   132          uint8_t *d = RCAST(uint8_t *, RCAST(void *, &rv));
   133          d[0] = s[1];
   134          d[1] = s[0];
   135          return rv;
   136  }
