   138  /*
   139   * swap an int
   140   */
   141  static uint32_t
   142  _cdf_tole4(uint32_t sv)
   143  {
   144          uint32_t rv;
   145          uint8_t *s = RCAST(uint8_t *, RCAST(void *, &sv));
   146          uint8_t *d = RCAST(uint8_t *, RCAST(void *, &rv));
   147          d[0] = s[3];
   148          d[1] = s[2];
   149          d[2] = s[1];
   150          d[3] = s[0];
   151          return rv;
   152  }
